<script setup lang="ts">
import { computed, ref } from 'vue';
import { analyzeImport, cancelImport, commitImport } from '../../api/imports.ts';
import type { DisplayIdentityReference, ImportMerchantDecision, StagedFile, StagedImportBatch, StagedTransaction } from '../../api/contracts.ts';
import { formatDate, formatMoney, formatSourceAmount } from '../../shared/format.ts';
import { UiButton, UiDialog, UiSelect } from '../../shared/ui';
import ImportMerchantDecisions from './ImportMerchantDecisions.vue';
import { canContinue, importSteps, initialDecision, needsReconciliation, previewRows, type DuplicateAction } from './model.ts';

const emit = defineEmits<{ imported: [] }>();
const openState = ref(false); const step = ref(0); const batch = ref<StagedImportBatch | null>(null); const busy = ref(false); const error = ref(''); const notice = ref('');
const decisions = ref(new Map<string, ImportMerchantDecision>()); const duplicates = ref(new Map<string, DuplicateAction>()); const reconciled = ref(new Set<string>()); const dragActive = ref(false);
const fileInput = ref<HTMLInputElement | null>(null);
const reviewMerchants = computed(() => batch.value?.merchants.filter((item) => item.needs_review) ?? []);
const knownMerchants = computed(() => (batch.value?.merchants.length ?? 0) - reviewMerchants.value.length);
const insertRows = computed(() => batch.value ? previewRows(batch.value, decisions.value, duplicates.value) : []);
const permanentDecisions = computed(() => [...decisions.value.values()].filter((item) => !['needs_review', 'exclude'].includes(item.resolution) && item.scope === 'exact').length);
const deferredDecisions = computed(() => [...decisions.value.values()].filter((item) => item.resolution === 'needs_review').length);
const excludedDecisions = computed(() => [...decisions.value.values()].filter((item) => item.resolution === 'exclude').length);
const reviewedDuplicateImports = computed(() => [...duplicates.value.values()].filter((item) => item === 'import').length);
const reviewedDuplicateSkips = computed(() => [...duplicates.value.values()].filter((item) => item === 'skip').length);
const nextEnabled = computed(() => !busy.value && canContinue(step.value, batch.value, decisions.value, duplicates.value, reconciled.value));
const totals = computed(() => (batch.value?.files ?? []).reduce((sum, file) => ({ parsed: sum.parsed + (file.parsed ?? 0), newRows: sum.newRows + (file.new_rows ?? 0), exact: sum.exact + (file.exact_duplicates ?? 0), possible: sum.possible + (file.possible_duplicates ?? 0), pending: sum.pending + (file.pending_rows ?? 0), plans: sum.plans + (file.installment_plans ?? 0) }), { parsed: 0, newRows: 0, exact: 0, possible: 0, pending: 0, plans: 0 }));

function open(): void { openState.value = true; error.value = ''; notice.value = ''; }
function close(): void { if (!busy.value) openState.value = false; }
function browse(): void { fileInput.value?.click(); }
async function analyze(file: File | undefined): Promise<void> {
  if (!file) return; busy.value = true; error.value = ''; notice.value = '';
  try { const previousBatchId = batch.value?.batch_id; const result = await analyzeImport(file); batch.value = result; step.value = 1; duplicates.value = new Map(); reconciled.value = new Set(); decisions.value = new Map(result.merchants.filter((item) => item.needs_review).map((merchant) => [merchant.merchant_normalized, initialDecision(merchant, result.display_identities)])); if (previousBatchId && previousBatchId !== result.batch_id) await cancelImport(previousBatchId); notice.value = `${result.files[0]?.filename || file.name} staged. Nothing was added to the database.`; }
  catch (caught) { error.value = caught instanceof Error ? caught.message : 'Could not analyze the file'; }
  finally { busy.value = false; if (fileInput.value) fileInput.value.value = ''; }
}
async function discardBatch(): Promise<void> {
  if (!batch.value || busy.value) return;
  busy.value = true; error.value = '';
  try { await cancelImport(batch.value.batch_id); batch.value = null; decisions.value = new Map(); duplicates.value = new Map(); reconciled.value = new Set(); step.value = 0; notice.value = 'Staged file discarded. The database was not changed.'; }
  catch (caught) { error.value = caught instanceof Error ? caught.message : 'Could not discard the staged file'; }
  finally { busy.value = false; }
}
function chooseFiles(event: Event): void {
  const files = (event.target as HTMLInputElement).files;
  if (files && files.length > 1) { error.value = 'Choose one statement at a time.'; return; }
  void analyze(files?.[0]);
}
function drop(event: DragEvent): void {
  dragActive.value = false;
  const files = event.dataTransfer?.files;
  if (files && files.length > 1) { error.value = 'Drop one statement at a time.'; return; }
  void analyze(files?.[0]);
}
function setDuplicate(id: string, value: string): void { const next = new Map(duplicates.value); if (value) next.set(id, value as DuplicateAction); else next.delete(id); duplicates.value = next; }
function setReconciled(filename: string, checked: boolean): void { const next = new Set(reconciled.value); if (checked) next.add(filename); else next.delete(filename); reconciled.value = next; }
function updateDecision(key: string, field: keyof ImportMerchantDecision, value: string): void {
  const current = decisions.value.get(key); if (!current) return; const next = { ...current, [field]: value, suggested_match: false } as ImportMerchantDecision;
  if (field === 'resolution') { if (value === 'needs_review') { next.category = 'Needs review'; next.scope = 'batch'; } if (value === 'provider') { const merchant = batch.value?.merchants.find((item) => item.merchant_normalized === key); next.category = merchant?.provider_category || 'Needs review'; next.scope = 'exact'; } if (value === 'link') next.scope = 'exact'; }
  const map = new Map(decisions.value); map.set(key, next); decisions.value = map;
}
function chooseIdentity(key: string, identity: DisplayIdentityReference): void { updateDecision(key, 'display_name', identity.display_name); updateDecision(key, 'canonical_group_id', identity.canonical_group_id); updateDecision(key, 'resolution', 'link'); if (identity.category_status === 'unanimous') updateDecision(key, 'category', identity.category!); }
function createIdentity(key: string, displayName: string): void { updateDecision(key, 'display_name', displayName); updateDecision(key, 'canonical_group_id', ''); updateDecision(key, 'resolution', 'create'); }
function identityFor(row: StagedTransaction): { display: string; category: string } { const decision = decisions.value.get(row.merchant_normalized); const merchant = batch.value?.merchants.find((item) => item.merchant_normalized === row.merchant_normalized); return { display: decision?.display_name || merchant?.display_name || row.merchant, category: decision?.category || merchant?.category || 'Needs review' }; }
function statusFor(row: StagedTransaction): string { if (row.reviewed_new) return 'Reviewed as new'; if (row.source_status === 'pending') return 'Pending · not final'; if (row.source_status === 'outside_cycle') return 'Outside billing cycle'; if (row.installment_number) return `Installment ${row.installment_number}/${row.installment_total ?? '?'}`; return 'Confirmed new'; }
function safeDate(value: string | null | undefined): string { return value ? formatDate(value) : '—'; }
function transactionAmount(row: StagedTransaction): string { return formatSourceAmount(row.amount ?? row.original_amount ?? 0, row.currency || row.original_currency || 'ILS'); }
function coverageDates(file: StagedFile): string {
  return (file.coverage ?? []).map((item) => item.purchase_date_from && item.purchase_date_to ? `${safeDate(item.purchase_date_from)}–${safeDate(item.purchase_date_to)}` : '').filter(Boolean).join(' · ') || 'No purchase-date coverage';
}
function coverageCards(file: StagedFile): string { return (file.coverage ?? []).length ? (file.coverage ?? []).map((item) => `•• ${item.card_last4}`).join(' · ') : file.card_last4 ? `•• ${file.card_last4}` : file.kind === 'income' ? 'Monthly income' : 'Card not detected'; }
function coverageAsOf(file: StagedFile): string | null { const values = (file.coverage ?? []).map((item) => item.statement_as_of_date).filter((item): item is string => Boolean(item)).sort(); return values.at(-1) ?? null; }
function finalizedRows(file: StagedFile): number { return Math.max(0, (file.parsed ?? 0) - (file.pending_rows ?? 0)); }
function sourceCounts(fileIndex: number): { scheduled: number; pending: number; outside: number } {
  if (!batch.value) return { scheduled: 0, pending: 0, outside: 0 };
  const rows = [...batch.value.new_transactions, ...batch.value.exact_duplicates, ...batch.value.possible_duplicates, ...batch.value.pending_transactions].filter((row) => row.file_index === fileIndex);
  const pending = rows.filter((row) => row.source_status === 'pending').length;
  const outside = rows.filter((row) => row.source_status === 'outside_cycle').length;
  return { scheduled: Math.max(0, rows.length - pending - outside), pending, outside };
}
function exactMatchContext(row: StagedTransaction): string {
  const match = row.matched_rows?.[0];
  if (!match) return row.matched_transaction_id ? `DB #${row.matched_transaction_id}` : '';
  return [`DB #${match.id}`, match.card_last4 ? `•• ${match.card_last4}` : '', match.billing_month ? `billed ${match.billing_month}` : '', match.merchant_raw && match.merchant_raw !== row.merchant ? match.merchant_raw : ''].filter(Boolean).join(' · ');
}
function next(): void { if (step.value < 4 && nextEnabled.value) step.value += 1; else if (step.value === 4 && nextEnabled.value) void commit(); }
async function commit(): Promise<void> {
  if (!batch.value) return; busy.value = true; error.value = '';
  try { const result = await commitImport({ batch_id: batch.value.batch_id, decisions: [...decisions.value.values()], duplicate_decisions: [...duplicates.value].map(([candidate_id, action]) => ({ candidate_id, action })), reconciled_files: [...reconciled.value] }); const inserted = result.results.reduce((sum, item) => sum + (item.inserted ?? 0), 0); batch.value = null; decisions.value = new Map(); duplicates.value = new Map(); reconciled.value = new Set(); step.value = 0; openState.value = false; emit('imported'); notice.value = `${inserted} transactions imported after a database backup.`; }
  catch (caught) { error.value = caught instanceof Error ? caught.message : 'Import failed'; }
  finally { busy.value = false; }
}
defineExpose({ open });
</script>

<template><UiDialog :open="openState" title-id="import-manager-title" close-label="Close import" size="analysis" @request-close="close">
  <template #header><div class="import-manager-head"><div><h2 id="import-manager-title">Import statements</h2><span>Analyze, review and reconcile before anything is written.</span></div><span v-if="batch" class="import-staged-badge">Staged · not saved</span></div></template>
  <nav class="import-steps" aria-label="Import steps"><button v-for="(name,index) in importSteps" :key="name" type="button" :class="{ active: step===index, done:index<step }" :disabled="(!batch&&index>0)||index>step" @click="step=index"><b>{{ index<step?'✓':index+1 }}</b><span>{{ name }}</span></button></nav>
  <div class="import-manager-content" :aria-busy="busy"><p v-if="busy" class="import-busy">{{ step===4?'Creating backup and importing…':'Analyzing the statement without changing your database…' }}</p><p v-if="error" class="transaction-editor-error" role="alert">{{ error }}</p><p v-if="notice" class="import-notice" role="status">{{ notice }}</p>
    <section v-if="!busy&&step===0" class="import-files-step"><div v-if="batch" class="import-callout staged-batch-callout"><span><strong>{{ batch.files[0]?.filename }}</strong> is staged. Choose another file to replace it or continue.</span><button type="button" @click="discardBatch">Discard staged file</button></div><button type="button" class="import-drop" :class="{ dragging:dragActive }" @click="browse" @dragover.prevent="dragActive=true" @dragleave.prevent="dragActive=false" @drop.prevent="drop"><strong>Drop one statement here or click to browse</strong><span>XLSX or PDF · one file per import · analysis is read-only</span></button><input ref="fileInput" type="file" accept=".xlsx,.pdf" hidden @change="chooseFiles"></section>
    <section v-else-if="!busy&&step===1&&batch"><div class="import-metrics"><div><span>Parsed rows</span><strong>{{ totals.parsed }}</strong></div><div><span>Confirmed new</span><strong>{{ totals.newRows }}</strong></div><div><span>Exact duplicates</span><strong>{{ totals.exact }}</strong></div><div><span>Needs review</span><strong>{{ totals.possible }}</strong></div><div><span>Pending</span><strong>{{ totals.pending }}</strong></div><div><span>Installment plans</span><strong>{{ totals.plans }}</strong></div></div>
      <div v-for="warning in batch.coverage_warnings" :key="`${warning.filename}-${warning.message}`" class="import-callout warning"><strong>Card ••{{ warning.card_last4 }} · {{ warning.filename }}</strong> — {{ warning.message }}<small v-if="warning.imports?.length">Related imports: {{ warning.imports.join(', ') }}</small></div>
      <div v-for="uploadError in batch.upload_errors" :key="uploadError.filename" class="import-callout warning"><strong>{{ uploadError.filename }}</strong> — {{ uploadError.error || uploadError.status }}</div>
      <div class="import-table-wrap"><table><thead><tr><th>File</th><th>Source</th><th>Coverage</th><th>Rows</th><th>Status</th></tr></thead><tbody><tr v-for="(file,fileIndex) in batch.files" :key="file.filename"><td><strong>{{ file.filename }}</strong><small>{{ file.format }}<template v-if="file.product_name"> · {{ file.product_name }}</template></small></td><td><strong>{{ (file.provider||file.kind).toUpperCase() }}</strong><small>{{ coverageCards(file) }}</small></td><td><strong>{{ file.statement_range||'—' }}</strong><small>{{ coverageDates(file) }}<template v-if="coverageAsOf(file)"> · data as of {{ safeDate(coverageAsOf(file)) }}</template></small></td><td><strong>{{ file.new_rows||0 }} confirmed new</strong><small>{{ file.exact_duplicates||0 }} exact · {{ file.possible_duplicates||0 }} review</small><small v-if="file.kind==='statement'">{{ sourceCounts(fileIndex).scheduled }} scheduled · {{ sourceCounts(fileIndex).pending }} pending · {{ sourceCounts(fileIndex).outside }} outside cycle</small></td><td><i :class="{ warning:file.status!=='ready' }">{{ file.status.replaceAll('_',' ') }}</i></td></tr></tbody></table></div>
      <div class="import-duplicate-section"><h3><span>Exact duplicates<small>These rows already exist and will not be inserted again.</small></span><b>{{ batch.exact_duplicates.length }} automatically excluded</b></h3><div v-for="row in batch.exact_duplicates" :key="`${row.filename}-${row.transaction_key}-${row.matched_transaction_id}`" class="import-duplicate-row"><span><strong>{{ row.merchant||'Income' }}</strong><small>{{ row.filename }} · {{ safeDate(row.transaction_date) }}</small></span><span><strong>{{ transactionAmount(row) }}</strong><small>{{ row.card_last4?`Incoming •• ${row.card_last4}`:'Income entry' }}</small></span><span><strong>Excluded automatically</strong><small>{{ row.reason||'Exact identity already exists' }}<template v-if="exactMatchContext(row)"> · {{ exactMatchContext(row) }}</template></small></span></div><p v-if="!batch.exact_duplicates.length">No exact duplicates found.</p></div>
      <div class="import-duplicate-section"><h3><span>Possible duplicates<small>Nothing uncertain is removed automatically. Decide what to do with every row.</small></span><b>{{ batch.possible_duplicates.length }} decisions required</b></h3><div v-for="row in batch.possible_duplicates" :key="row.candidate_id" class="import-duplicate-row"><span><strong>{{ row.merchant }}</strong><small>Incoming · {{ safeDate(row.transaction_date) }} · {{ row.filename }}</small></span><span><strong>{{ transactionAmount(row) }}</strong><small>Existing DB {{ row.matched_transaction_ids?.map(id=>`#${id}`).join(', ') || 'match' }}<template v-if="row.matched_rows?.[0]?.billing_month"> · billed {{ row.matched_rows[0].billing_month }}</template></small></span><label><span>{{ row.reason }}</span><UiSelect :model-value="duplicates.get(row.candidate_id||'')||''" density="dense" @update:model-value="setDuplicate(row.candidate_id||'', $event)"><option value="">Choose action…</option><option value="skip">Treat as duplicate</option><option value="import">Import as new</option></UiSelect></label></div><p v-if="!batch.possible_duplicates.length">No uncertain matches need review.</p></div>
    </section>
    <section v-else-if="!busy&&step===2&&batch"><div class="import-callout"><strong>{{ knownMerchants }} merchants matched existing rules.</strong> Review {{ reviewMerchants.length }} unfamiliar merchants. “Needs review” safely imports without a permanent rule.</div><ImportMerchantDecisions v-if="reviewMerchants.length" :merchants="reviewMerchants" :decisions="decisions" :categories="batch.categories" :identities="batch.display_identities" @update="updateDecision" @identity="chooseIdentity" @create-identity="createIdentity" /><div v-else class="import-empty">All merchants matched approved database rules.</div></section>
    <section v-else-if="!busy&&step===3&&batch"><div class="import-callout warning"><strong>Reconciliation compares only the scheduled statement charge.</strong> Pending and outside-cycle transactions remain visible separately and do not distort that total.</div><div class="import-table-wrap"><table><thead><tr><th>File</th><th>Parsed total</th><th>Official total</th><th>Difference</th><th>Confirmation</th></tr></thead><tbody><tr v-for="(file,fileIndex) in batch.files" :key="file.filename"><td><strong>{{ file.filename }}</strong><small>{{ (file.provider||file.kind).toUpperCase() }}<template v-if="file.card_last4"> · •• {{ file.card_last4 }}</template></small></td><td><strong>{{ formatMoney(file.reconciliation?.parsed_total||0) }}</strong><small v-if="file.kind==='statement'">{{ sourceCounts(fileIndex).scheduled }} scheduled · {{ sourceCounts(fileIndex).pending }} pending excluded · {{ sourceCounts(fileIndex).outside }} outside-cycle excluded</small><small v-else>{{ finalizedRows(file) }} parsed rows</small></td><td>{{ file.reconciliation?.official_total==null?'Check original':formatMoney(file.reconciliation.official_total) }}</td><td>{{ file.reconciliation?.difference==null?'—':formatMoney(file.reconciliation.difference) }}</td><td><label v-if="needsReconciliation(file)" class="reconcile-check"><input type="checkbox" :checked="reconciled.has(file.filename)" @change="setReconciled(file.filename,($event.target as HTMLInputElement).checked)"> I reviewed {{ file.reconciliation?.status==='mismatch'?'the mismatch':'the total' }}</label><i v-else>{{ file.reconciliation?.status==='matched'?'Matched':'No check needed' }}</i></td></tr></tbody></table></div></section>
    <section v-else-if="!busy&&step===4&&batch"><div class="import-approve"><div><h3>Safety checks complete</h3><ul><li>1 statement parsed · {{ insertRows.length }} rows to add · {{ batch.exact_duplicates.length }} exact duplicates excluded</li><li>{{ reviewedDuplicateSkips }} possible duplicates skipped · {{ reviewedDuplicateImports }} confirmed as new</li><li>{{ knownMerchants }} merchants matched existing database rules</li><li>{{ permanentDecisions }} permanent rules · {{ deferredDecisions }} left for review · {{ excludedDecisions }} excluded</li><li>{{ [...reconciled].length }} statement totals manually checked</li><li>A verified database backup will be created immediately before any records are written</li></ul></div><div><h3>Ready to import</h3><p><span>Statement</span><strong>1</strong></p><p><span>New transaction rows</span><strong>{{ insertRows.length }}</strong></p><p><span>Duplicates skipped</span><strong>{{ batch.exact_duplicates.length+reviewedDuplicateSkips }}</strong></p><p><span>Known + reviewed merchants</span><strong>{{ batch.merchants.length-deferredDecisions }}</strong></p><p><span>Still needs review</span><strong>{{ deferredDecisions }}</strong></p><div class="import-callout">Nothing has been added yet. Approve &amp; import atomically saves the reviewed statement or rolls it all back.</div></div></div><div class="import-preview"><h3><span>Transactions to be inserted<small>Complete read-only preview after duplicate and exclusion decisions</small></span><b>{{ insertRows.length }} rows</b></h3><div class="import-table-wrap"><table><thead><tr><th>Date</th><th>Merchant</th><th>Category</th><th>Amount</th><th>Card</th><th>Status</th></tr></thead><tbody><tr v-for="row in insertRows" :key="`${row.filename}-${row.transaction_key}-${row.candidate_id}`"><td><strong>{{ safeDate(row.billing_date||row.transaction_date) }}</strong><small>{{ row.billing_date&&row.transaction_date!==row.billing_date?`Purchased ${safeDate(row.transaction_date)}`:row.filename }}</small></td><td><strong>{{ identityFor(row).display }}</strong><small>{{ row.merchant }}</small></td><td>{{ identityFor(row).category }}</td><td><strong>{{ transactionAmount(row) }}</strong></td><td>{{ row.card_last4?`•• ${row.card_last4}`:'—' }}</td><td><i>{{ statusFor(row) }}</i></td></tr></tbody></table></div></div><div v-if="batch.pending_transactions.length" class="import-preview pending"><h3><span>Pending—not imported<small>Provider authorizations can be finalized by a later statement.</small></span><b>{{ batch.pending_transactions.length }} rows</b></h3><div class="import-table-wrap"><table><thead><tr><th>Date</th><th>Merchant</th><th>Category</th><th>Amount</th><th>Card</th><th>Status</th></tr></thead><tbody><tr v-for="row in batch.pending_transactions" :key="`${row.filename}-${row.transaction_key}`"><td><strong>{{ safeDate(row.billing_date||row.transaction_date) }}</strong><small>{{ row.filename }}</small></td><td><strong>{{ identityFor(row).display }}</strong><small>{{ row.merchant }}</small></td><td>{{ identityFor(row).category }}</td><td><strong>{{ transactionAmount(row) }}</strong></td><td>{{ row.card_last4?`•• ${row.card_last4}`:'—' }}</td><td><i>Pending · not final</i></td></tr></tbody></table></div></div></section>
  </div><template #footer><div class="import-manager-footer"><span>{{ ['Select files to analyze.','Exact duplicates are excluded; review uncertain matches.','Resolve unfamiliar merchants or leave them for later.','Compare parsed totals with original statements.','Approve only after reviewing every inserted row.'][step] }}</span><div><UiButton :disabled="busy||step===0" @click="step-=1">Back</UiButton><UiButton variant="primary" :disabled="!nextEnabled" :busy="busy" @click="next">{{ step===4?'Approve & import':'Continue' }}</UiButton></div></div></template>
</UiDialog></template>
